                            Guid = new Guid("5352414d-0000-4d00-0000-000000000000"),
                            Order = 77,
                            Text = "Сегодня я чувствую себя DPS-ом в нашей семье. Ты — танк, который всё агрит на себя. А я просто пытаюсь выжить."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-4e00-0000-000000000000"),
                            Order = 78,
                            Text = "У тебя сегодня был тяжёлый день? Давай я сделаю тебе чай и мы вместе посмотрим что-нибудь тупое."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-4f00-0000-000000000000"),
                            Order = 79,
                            Text = "Ты когда-нибудь задумывался(-ась), почему я до сих пор с тобой? Потому что ты забываешь закрывать холодильник, и я экономлю на кондиционере."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5000-0000-000000000000"),
                            Order = 80,
                            Text = "Я тут узнал(-а), что смех продлевает жизнь. Так что смейся, я буду твоим личным стендап-комиком."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5100-0000-000000000000"),
                            Order = 81,
                            Text = "Ты знаешь, что я люблю тебя больше всего на свете? Но если ты тронешь мой зарядник без спроса — пеняй на себя."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5200-0000-000000000000"),
                            Order = 82,
                            Text = "Сегодня я намерен(-а) выиграть у тебя в споре. У меня уже заготовлено 5 аргументов и 3 манипуляции."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5300-0000-000000000000"),
                            Order = 83,
                            Text = "Ты бы мог(-ла) хотя бы притвориться, что слушаешь меня, когда я рассказываю о своём дне. А не просто кивать и говорить «ага, кек»."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5400-0000-000000000000"),
                            Order = 84,
                            Text = "Если бы любовь измерялась в гигабайтах, у нас был бы целый дата-центр."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5500-0000-000000000000"),
                            Order = 85,
                            Text = "Я нашел(-ла) твой список желаний в стиме. Теперь я знаю, что дарить тебе на ближайшие 10 лет."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5600-0000-000000000000"),
                            Order = 86,
                            Text = "Предлагаю сегодня устроить свидание. Я готовлю ужин, ты моешь посуду. Справедливо?"
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5700-0000-000000000000"),
                            Order = 87,
                            Text = "Ты знаешь, что я готова простить тебе всё, кроме пустого пакета молока в холодильнике."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5800-0000-000000000000"),
                            Order = 88,
                            Text = "Сегодня я решил(-а) стать твоим саппортом в реальной жизни. Уже приготовил(-а) баффы: чай, печеньки и твою любимую футболку."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5900-0000-000000000000"),
                            Order = 89,
                            Text = "Ты думаешь, я не замечаю, что ты тайком ешь конфеты? Я веду учёт. У нас проблемы."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5a00-0000-000000000000"),
                            Order = 90,
                            Text = "Я тебя очень люблю, но если ты не научишься вовремя ложиться спать — я отключу рубильник."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5b00-0000-000000000000"),
                            Order = 91,
                            Text = "Давай сегодня устроим день наоборот: ты готовишь ужин, а я играю в твои игры. Спойлер: я выиграю быстрее."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5c00-0000-000000000000"),
                            Order = 92,
                            Text = "Ты мой герой. Особенно когда выносишь мусор без напоминания. Редкий скилл, кстати."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5d00-0000-000000000000"),
                            Order = 93,
                            Text = "Если ты сейчас не обнимешь меня, я буду дуться целый час. И нет, босс в рейде не подождёт."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5e00-0000-000000000000"),
                            Order = 94,
                            Text = "Я тут подумал(-а): а что если твоя любовь к играм — это просто способ проводить больше времени со мной? Ну, теоретически..."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-5f00-0000-000000000000"),
                            Order = 95,
                            Text = "Твой скилл «лежание на диване» прокачан до максимума. Может, вложишь очки в «мытьё посуды»?"
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-6000-0000-000000000000"),
                            Order = 96,
                            Text = "Сегодня я разрешаю тебе играть сколько хочешь. Взамен ты завтра идёшь со мной по магазинам. Без нытья."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-6100-0000-000000000000"),
                            Order = 97,
                            Text = "У нас в квартире завёлся пылесос-призрак. Он включается только когда я говорю «уберись»."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-6200-0000-000000000000"),
                            Order = 98,
                            Text = "Ты знаешь, что я променял(-а) бы все свои скины на одну минуту твоего искреннего внимания? Ладно, шучу. Не на все."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-6300-0000-000000000000"),
                            Order = 99,
                            Text = "Если ты прочитал(-а) это сообщение и не улыбнулся(-ась) — я обижусь. А если улыбнулся(-ась) — иди сюда, я тебя поцелую."
                        },
                        new
                        {
                            Guid = new Guid("5352414d-0000-6400-0000-000000000000"),
                            Order = 100,
                            Text = "Спасибо, что ты есть. Даже когда бесишь, не моешь посуду и громко смеёшься в дискорде в 3 часа ночи. Я тебя люблю."
                        });
                });

